package net.minecraft.util; public enum EnumFacing { DOWN(0,-1,0),UP(0,1,0),NORTH(0,0,-1),SOUTH(0,0,1),WEST(-1,0,0),EAST(1,0,0); public static final EnumFacing[] VALUES=values(); public final int x,y,z; EnumFacing(int x,int y,int z){this.x=x;this.y=y;this.z=z;} public EnumFacing getOpposite(){return VALUES[ordinal()^1];} }
